namespace BB84.SourceGenerators.Attributes;

/// <summary>
/// Indicates that the decorated field or partial property should be excluded from notification property generation.
/// Fields marked with this attribute will not have properties generated by the
/// <see cref="GenerateNotificationsAttribute"/> source generator. Partial properties marked with this
/// attribute are implemented as plain properties without change notification.
/// </summary>
[AttributeUsage(AttributeTargets.Field | AttributeTargets.Property, Inherited = false, AllowMultiple = false)]
internal sealed class ExcludeFromNotificationAttribute : Attribute;
